program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != bg]
    frame = max(colors, key=lambda c: counts[c])
    markers = [c for c in colors if c != frame]
    if not markers:
        return out
    marker_color = markers[0]
    cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == frame]
    # The frame consists of two short, opposite edge bars.
    vertical = {}
    for c in (0, w-1):
        vals = sorted(r for r,x in cells if x == c)
        if vals: vertical[c] = vals
    horizontal = {}
    for r in (0, h-1):
        vals = sorted(c for y,c in cells if y == r)
        if vals: horizontal[r] = vals
    if len(vertical) >= 2:
        axis = 'v'
        bars = [(('left' if c == 0 else 'right'), c, vals) for c,vals in vertical.items()]
    else:
        axis = 'h'
        bars = [(('top' if r == 0 else 'bottom'), r, vals) for r,vals in horizontal.items()]
    if len(bars) < 2:
        return out
    # Each marker projects its coordinate along one bar onto the opposite bar.
    marker_cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker_color]
    for r,c in marker_cells:
        along = r if axis == 'v' else c
        chosen = min(bars, key=lambda b: 0 if min(b[2]) <= along <= max(b[2]) else min(abs(along-min(b[2])), abs(along-max(b[2]))))
        side, edge, vals = chosen
        offset = along - min(vals)
        other = next(b for b in bars if b is not chosen)
        other_side, other_edge, other_vals = other
        projected = min(other_vals) + offset
        if projected > max(other_vals):
            continue
        # Extend the matching point on the opposite edge across the board.
        if axis == 'v':
            rr = projected
            if other_side == 'left':
                for cc in range(0, w):
                    if grid[rr][cc] != frame: out[rr][cc] = marker_color
            else:
                for cc in range(w-1, -1, -1):
                    if grid[rr][cc] != frame: out[rr][cc] = marker_color
            # Points lying beside the left/right bar extend from it to the marker.
            if side == 'left':
                for cc in range(1, c):
                    if grid[r][cc] not in (frame, marker_color): out[r][cc] = marker_color
            elif side == 'right':
                for cc in range(c+1, w-1):
                    if grid[r][cc] not in (frame, marker_color): out[r][cc] = marker_color
        else:
            rr = projected
            if other_side == 'top':
                for y in range(0, h):
                    if grid[y][rr] != frame: out[y][rr] = marker_color
            else:
                for y in range(h-1, -1, -1):
                    if grid[y][rr] != frame: out[y][rr] = marker_color
    for r,c in marker_cells:
        out[r][c] = 4
    return out
'''
